    features: ["Third-party API integrations", "Custom REST and GraphQL APIs", "Webhooks and event-driven sync", "OAuth2, API keys and JWT security", "Rate limiting and retries", "OpenAPI / Swagger documentation", "Integration monitoring and alerts", "Legacy system connectors"],
    benefits: ["No more copying data between systems", "Reliable sync with error handling and alerts", "Documented APIs your team can extend"],
    useCases: ["CRM and marketing tools", "Payments and accounting", "E-commerce, ERP and couriers", "WhatsApp and messaging", "Mobile app backends", "Legacy systems without APIs"],
    faqs: [{"question": "How much do API integration services cost?", "answer": "A single integration between two systems with a documented API is a short fixed-price project, often within a week or two of work. Multi-system integrations, custom APIs and legacy connectors are quoted per milestone after we review the systems involved."}, {"question": "Which systems can you integrate?", "answer": "Most systems with an API or webhooks, including HubSpot, Salesforce, Zoho, Xero, QuickBooks, Stripe, Shopify, WooCommerce, Odoo, WhatsApp Business, Google Workspace, Microsoft 365 and local payment and courier services."}, {"question": "What if a system has no API?", "answer": "We can use scheduled file exports, database connections or a small connector service, with checks so data is not duplicated or lost."}, {"question": "Do you provide documentation?", "answer": "Yes. We document every API with OpenAPI (Swagger) specs and Postman collections, and every integration with a short runbook."}, {"question": "How do you keep integrations secure?", "answer": "We store credentials in a secrets manager, use OAuth or scoped API keys with least privilege, encrypt traffic and log every sync so problems can be traced."}],
    useCaseDetails: {"CRM and marketing tools": "Leads from forms, ads and calls created in your CRM automatically, with follow-up sequences triggered.", "Payments and accounting": "Payments, invoices and refunds synced into Xero, QuickBooks or your ERP without retyping.", "E-commerce, ERP and couriers": "Orders, stock and shipping labels flowing between your store, ERP and courier accounts.", "WhatsApp and messaging": "Order updates, reminders and support conversations through the WhatsApp Business API.", "Mobile app backends": "Secure APIs for iOS and Android apps with authentication and versioning.", "Legacy systems without APIs": "Connectors for older desktop or on-premise systems so they can share data with modern tools."},
    guideTitle: "API Integration: How We Make Systems Work Together",
    guide: [{"heading": "Map the data first", "content": "We list which system owns each piece of data, such as customers, orders, stock or invoices, and in which direction it should flow. That avoids the most common integration problem: two systems overwriting each other."}, {"heading": "Real-time or scheduled", "content": "Webhooks give near real-time updates when systems support them; scheduled syncs suit large batches or systems without webhooks. Many integrations use both, with a nightly check that catches anything missed."}, {"heading": "Built to fail safely", "content": "External APIs go down, change and rate-limit requests. Our integrations retry with backoff, queue requests, alert your team when something needs attention and never silently drop data."}, {"heading": "Custom APIs for your own products", "content": "For web and mobile apps we design clean REST or GraphQL APIs with authentication, versioning, rate limits and OpenAPI documentation, so future developers and partners can build on them."}, {"heading": "Monitoring after go-live", "content": "Every integration gets logs and alerts. On a monthly support plan we watch them, update them when providers change their APIs and add new connections as your tools change."}],
    process: [{"step": "01", "title": "Review Systems", "desc": "Check the APIs, data and limits of every system involved."}, {"step": "02", "title": "Data Map", "desc": "Agree which system owns each record and how data flows."}, {"step": "03", "title": "Build & Test", "desc": "Build the integration with retries, logging and test data."}, {"step": "04", "title": "Go Live", "desc": "Switch on gradually and reconcile records with your team."}, {"step": "05", "title": "Monitor", "desc": "Alerts, documentation and updates when providers change."}],
